};

export default LoadingStage1;
```

### LoadingStage2.js:
```jsx
import React from 'react';
import { useRef, useEffect } from 'react';

const LoadingStage2 = () => {
  const loadingBarRef = useRef(null);

  useEffect(() => {
    const loadingBar = loadingBarRef.current;
    const width = 0;
    const increment = 5;
    const id = setInterval(() => {
      if (width >= 100) {
        clearInterval(id);
      } else {
        width += increment;
        loadingBar.style.width = `${width}%`;
      }
    }, 50);

    return () => clearInterval(id);
  }, []);

  return (
    <div className="relative h-screen flex items-center justify-center bg-black">
      <div className="relative w-3/4 h-3/4 bg-terminal rounded-lg overflow-hidden">
        <div className="absolute w-full h-full bg-scanlines animate-scanlines"></div>
