```jsx
import React, { useState, useEffect } from 'react';
import LoadingStage1 from './LoadingStage1';
import LoadingStage2 from './LoadingStage2';

const App = () => {
  const [loadingStage, setLoadingStage] = useState(1);

  useEffect(() => {
    const timer = setTimeout(() => {
      setLoadingStage(2);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="flex h-screen w-screen">
      {loadingStage === 1 && <LoadingStage1 />}
      {loadingStage === 2 && <LoadingStage2 />}
    </div>
  );
};

export default App;
