const express = require('express');
const axios = require('axios');
const cors = require('cors');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
app.use(cors());

const API_KEY = process.env.API_KEY;

const footballApiUrl = 'https://api.football-data.org/v2/matches';

app.get('/games/:team1/:team2', async (req, res) => {
  const { team1, team2 } = req.params;

  try {
    const response = await axios.get(`${footballApiUrl}/2021-22/en.summary?limit=10&status=FINISHED&teamid=${team1}&teamid=${team2}`, {
      headers: {
        'X-Auth-Token': API__KEY
      }
    });

    const games = response.data.matches;

    if (games.length === 0) {
      return res.status(404).json({ message: 'No games found between the selected teams' });
    }

    res.json(games);
  } catch (error) {
    console.error(error);
    res.status(500).json({ message: 'An error occurred while fetching the games' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

// 3. Create a simple UI to select two teams

