let readline = require('readline').createInterface({
    input: process.stdin,
    output: process.stdout
});

let min = 1;
let max = 100;
let guess = Math.floor((min + max) / 2);

console.log(`Think of a number between ${min} and ${max}.`);

function askQuestion() {
    readline.question(`Is your number ${guess}? (yes/more/less) `, answer => {
        if (answer.toLowerCase() === 'yes') {
            console.log(`I guessed your number! It's ${guess}!`);
            readline.close();
        } else if (answer.toLowerCase() === 'more') {
            min = guess + 1;
            guess = Math.floor((min + max) / 2);
            askQuestion();
        } else if (answer.toLowerCase() === 'less') {
            max = guess - 1;
            guess = Math.floor((min + max) / 2);
            askQuestion();
        } else {
            console.log('Invalid input. Please answer "yes", "more", or "less".');
            askQuestion();
        }
    });
}

askQuestion();
```

