```javascript
function computerGuessNumber(min, max) {
  const userNumber = Math.floor(Math.random() * (max - min + 1)) + min;
  let guess;

  while (true) {
    guess = Math.floor((min + max) / 2);
    console.log(`Is your number more, less, or equal to ${guess}?`);

    const userResponse = prompt("Enter 'more', 'less', or 'equal'").toLowerCase();

    if (userResponse === "equal") {
      console.log("The computer guessed your number!");
      break;
    } else if (userResponse === "more") {
      min = guess + 1;
    } else if (userResponse === "less") {
      max = guess - 1;
    } else {
      console.log("Invalid input. Please enter 'more', 'less', or 'equal'.");
      continue;
    }
  }
}

// Example usage:
